    46  static void
    47  mpz_set_int(mrb_state *mrb, mpz_t *y, mrb_int v)
    48  {
    49    mp_limb u;
    50    size_t len;
    51
    52    if (v == 0) {
    53      y->sn=0;
    54      u = 0;
    55    }
    56    else if (v > 0) {
    57      y->sn = 1;
    58      u = v;
    59    }
    60    if (v < 0) {
    61      y->sn = -1;
    62      if (v == MRB_INT_MIN) u = v;
    63      else u = -v;
    64    }
    65    if ((u & LC) == 0) len = 1;
    66    else len = 2;
    67    mpz_realloc(mrb, y, len);
    68    y->p[0] = u & LMAX;
    69    if (len > 1) y->p[1] = (u & LC) >> DIGITBITS;
    70  }
