    99  static void
   100  mpz_set(mrb_state *mrb, mpz_t *y, mpz_t *x)
   101  {
   102    size_t i,k = x->sz;
   103
   104    mpz_realloc(mrb, y, (size_t)k);
   105    for (i=0;i < k; i++)
   106      (y->p)[i] = (x->p)[i];
   107
   108    for (;i<y->sz;i++)
   109      (y->p)[i] = 0;
   110
   111    y->sn = x->sn;
   112  }
