   114  /* z = x + y, without regard for sign */
   115  static void
   116  uadd(mrb_state *mrb, mpz_t *z, mpz_t *x, mpz_t *y)
   117  {
   118    mp_limb c;
   119    size_t i;
   120    mpz_t *t;
   121
   122    if (y->sz < x->sz) {
   123      t=x; x=y; y=t;
   124    }
   125
   126    /* now y->sz >= x->sz */
   127
   128    mpz_realloc(mrb, z, (size_t)((y->sz)+1));
   129
   130    c=0;
   131    for (i=0; i<x->sz; i++) {
   132      if ((z->p[i] = y->p[i] + x->p[i] + c) & CMASK) {
   133        c=1;
   134        (z->p[i]) &=LMAX;
   135      }
   136      else
   137        c=0;
   138    }
   139    for (;i<y->sz; i++) {
   140      if ((z->p[i] = (y->p[i] + c)) & CMASK)
   141        z->p[i]=0;
   142      else
   143        c=0;
   144    }
   145    (z->p)[y->sz]=c;
   146  }
