   148  /* z = y - x, ignoring sign */
   149  /* precondition: abs(y) >= abs(x) */
   150  static void
   151  usub(mrb_state *mrb, mpz_t *z, mpz_t *y, mpz_t *x)
   152  {
   153    mp_limb b,m;
   154    mpz_realloc(mrb, z, (size_t)(y->sz));
   155    b=0;
   156    for (size_t i=0;i<y->sz;i++) {
   157      m=((y->p)[i]-b)-dg(x,i);
   158      if (m < 0) {
   159        b = 1;
   160        m = LMAX + 1 + m;
   161      }
   162      else
   163        b = 0;
   164      z->p[i] = m;
   165    }
   166  }
