   168  /* compare abs(x) and abs(y) */
   169  static int
   170  ucmp(mpz_t *y, mpz_t *x)
   171  {
   172    size_t i;
   173    for (i=imax(x->sz,y->sz)-1;;i--) {
   174      if (dg(y,i) < dg(x,i))
   175        return (-1);
   176      else if (dg(y,i) > dg(x,i))
   177        return 1;
   178      if (i == 0) break;
   179    }
   180    return 0;
   180    return 0;
   181  }
