   200  /* z = x + y */
   201  static void
   202  mpz_add(mrb_state *mrb, mpz_t *zz, mpz_t *x, mpz_t *y)
   203  {
   204    int mg;
   205    mpz_t z;
   206    if (x->sn == 0) {
   207      mpz_set(mrb, zz, y);
   208      return;
   209    }
   210    if (y->sn == 0) {
   211      mpz_set(mrb, zz, x);
   212      return;
   213    }
   214    mpz_init(mrb, &z);
   215
   216    if (x->sn > 0 && y->sn > 0) {
   217      uadd(mrb, &z, x, y);
   218      z.sn = 1;
   219    }
   220    else if (x->sn < 0 && y->sn < 0) {
   221      uadd(mrb, &z, x, y);
   222      z.sn = -1;
   223    }
   224    else {
   225      /* signs differ */
   226      if ((mg = ucmp(x,y)) == 0) {
   227        zero(&z);
   228      }
   229      else if (mg > 0) {  /* abs(y) < abs(x) */
   230        usub(mrb, &z, x, y);
   231        z.sn = (x->sn > 0 && y->sn < 0) ? 1 : (-1);
   232      }
   233      else { /* abs(y) > abs(x) */
   234        usub(mrb, &z, y, x);
   235        z.sn = (x->sn < 0 && y->sn > 0) ? 1 : (-1);
   236      }
   237    }
   238    mpz_set(mrb,zz,&z);
   239    mpz_clear(mrb,&z);
   240  }
