   242  /* z = x - y  -- just use mpz_add - I'm lazy */
   243  static void
   244  mpz_sub(mrb_state *mrb, mpz_t *z, mpz_t *x, mpz_t *y)
   245  {
   246    mpz_t u;
   247    mpz_init(mrb, &u);
   248    mpz_set(mrb, &u, y);
   249    u.sn = -(u.sn);
   250    mpz_add(mrb, z, x, &u);
   251    mpz_clear(mrb, &u);
   252  }
