   264  /* w = u * v */
   265  static void
   266  mpz_mul(mrb_state *mrb, mpz_t *ww, mpz_t *u, mpz_t *v)
   267  {
   268    size_t i,j;
   269    mp_limb t0,t1,t2,t3;
   270    mp_limb cc;
   271    mpz_t w;
   272
   273    if (uzero(u) || uzero(v)) {
   274      mpz_set_int(mrb, ww, 0);
   275      return;
   276    }
   277    mpz_init(mrb, &w);
   278    mpz_realloc(mrb, &w, (size_t)(u->sz + v->sz));
   279    for (j=0; j < 2*u->sz; j++) {
   280      cc = (mp_limb)0;
   281      t3 = hd(u,j);
   282      for (i=0; i < 2*v->sz; i++) {
   283        t0 = t3 * hd(v,i);
   284        t1 = HIGH(t0); t0 = LOW(t0);
   285        if ((i+j)%2)
   286          t2 = HIGH(w.p[(i+j)/2]);
   287        else
   288          t2 = LOW(w.p[(i+j)/2]);
   289        t2 += cc;
   290        if (t2 & HCMASK) {
   291          cc = 1; t2&=HLMAX;
   292        }
   293        else
   294          cc = 0;
   295        t2 += t0;
   296        if (t2 & HCMASK) {
   297          cc++ ; t2&=HLMAX;
   298        }
   299        cc+=t1;
   300        if ((i+j)%2)
   301          w.p[(i+j)/2] = LOW(w.p[(i+j)/2]) |
   302            (t2 << HALFDIGITBITS);
   303        else
   304          w.p[(i+j)/2] = (HIGH(w.p[(i+j)/2]) << HALFDIGITBITS) | t2;
   305      }
   306      if (cc) {
   307        if ((j+i)%2)
   308          w.p[(i+j)/2] += cc << HALFDIGITBITS;
   309        else
   310          w.p[(i+j)/2] += cc;
   311      }
   312    }
   313    w.sn = (u->sn) * (v->sn);
   314    mpz_set(mrb, ww, &w);
   315    mpz_clear(mrb, &w);
   316  }
