   327  /* number of leading zero bits in digit */
   328  static int
   329  lzb(mp_limb x)
   330  {
   331  #if (defined(__GNUC__) || __has_builtin(__builtin_clz))
   332    /* subtract 2 because DIGITBITS = LONGBITS-2 */
   333    if (sizeof(mp_limb) == sizeof(long long))
   334      return __builtin_clzll(x)-2;
   335    else if (sizeof(mp_limb) == sizeof(int))
   336      return __builtin_clz(x)-2;
   337  #endif
   338
   339    mp_limb i; int j=0;
   340
   341    for (i = ((mp_limb)1 << (DIGITBITS-1)); i && !(x&i) ; j++,i>>=1)
   342      ;
   343    return j;
   344  }
