   346  /* c1 = a>>n */
   347  /* n must be < DIGITBITS */
   348  static void
   349  urshift(mrb_state *mrb, mpz_t *c1, mpz_t *a, size_t n)
   350  {
   351    mp_limb cc = 0;
   352    mrb_assert(n < DIGITBITS);
   353    if (n == 0)
   354      mpz_set(mrb, c1, a);
   355    else {
   356      mpz_t c; int i;
   357      mp_limb rm = (((mp_limb)1<<n) - 1);
   358      mpz_init(mrb,&c); mpz_realloc(mrb,&c,(size_t)(a->sz));
   359      for (i=a->sz-1; i>=0; i--) {
   360        c.p[i] = ((a->p[i] >> n) | cc) & LMAX;
   360        c.p[i] = ((a->p[i] >> n) | cc) & LMAX;
   361        cc = (a->p[i] & rm) << (DIGITBITS - n);
   362      }
   363      mpz_set(mrb,c1,&c);
   364      mpz_clear(mrb,&c);
   365    }
   366  }
