   368  /* c1 = a<<n */
   369  /* n must be < DIGITBITS */
   370  static void
   371  ulshift(mrb_state *mrb, mpz_t *c1, mpz_t *a, size_t n)
   372  {
   373    mp_limb cc = 0;
   374    mrb_assert(n < DIGITBITS);
   375    if (n == 0)
   376      mpz_set(mrb,c1,a);
   377    else {
   378      mpz_t c; size_t i;
   379      mp_limb rm = (((mp_ulimb)1<<n) - 1) << (DIGITBITS-n);
   380      mpz_init(mrb,&c); mpz_realloc(mrb,&c,(size_t)(a->sz + 1));
   381      for (i=0; i<a->sz; i++) {
   382        c.p[i] = (((mp_ulimb)a->p[i] << n) | cc) & LMAX;
   383        cc = (a->p[i] & rm) >> (DIGITBITS-n);
   384      }
   385      c.p[i] = cc;
   386      mpz_set(mrb,c1,&c);
   387      mpz_clear(mrb,&c);
   388    }
   389  }
