   391  /* internal routine to compute x/y and x%y ignoring signs */
   392  static void
   393  udiv(mrb_state *mrb, mpz_t *qq, mpz_t *rr, mpz_t *xx, mpz_t *yy)
   394  {
   395    mpz_t q, x, y, r;
   396    int ns,f,ccc=0;
   397    int xd,yd,i,j;
   398    mp_limb zz,z,qhat,b,u,m;
   399
   400    if (uzero(yy))
   401      return;
   402    mpz_init(mrb,&q); mpz_init(mrb,&x);mpz_init(mrb,&y);mpz_init(mrb,&r);
   403    mpz_realloc(mrb,&x,(size_t)((xx->sz)+1));
   404    yd = digits(yy);
   405    ns = lzb(yy->p[yd-1]);
   406    ulshift(mrb,&x,xx,ns);
   407    ulshift(mrb,&y,yy,ns);
   408    xd = digits(&x);
   409    mpz_realloc(mrb,&q,(size_t)xd);
   410    xd*=2; yd*=2;
   411    z = hd(&y,yd-1);
   412    for (j=(xd-yd);j>=0;j--) {
   413      if (z == LMAX)
   414        qhat = hd(&x,j+yd);
   415      else {
   416        qhat = ((hd(&x,j+yd)<< HALFDIGITBITS) + hd(&x,j+yd-1)) / (z+1);
   417      }
   418      b = 0; zz=0;
   419      if (qhat) {
   420        for (i=0; i<yd; i++) {
   421          zz = qhat * hd(&y,i);
   422          u = hd(&x,i+j);
   423          u-=b;
   424          if (u<0) {
   425            b=1; u+=HLMAX+1;
   426          }
   427          else
   428            b=0;
   429          u-=LOW(zz);
   430          if (u < 0) {
   431            b++;
   432            u+=HLMAX+1;
   433          }
   434          b+=HIGH(zz);
   435          if ((i+j)%2)
   436            x.p[(i+j)/2] = LOW(x.p[(i+j)/2]) | (u << HALFDIGITBITS);
   437          else
   438            x.p[(i+j)/2] = (HIGH(x.p[(i+j)/2]) << HALFDIGITBITS) | u;
   439        }
   440        if (b) {
   441          if ((j+i)%2)
   442            x.p[(i+j)/2] -= b << HALFDIGITBITS;
   443          else
   444            x.p[(i+j)/2] -= b;
   445        }
   446      }
   447      for (;;zz++) {
   448        f=1;
   449        if (!hd(&x,j+yd)) {
   450          for (i=yd-1; i>=0; i--) {
   451            if (hd(&x,j+i) > hd(&y,i)) {
   452              f=1;
   453              break;
   454            }
   455            if (hd(&x,j+i) < hd(&y,i)) {
   456              f=0;
   457              break;
   458            }
   459          }
   460        }
   461        if (!f)
   462          break;
   463        qhat++;
   464        ccc++;
   465        b=0;
   466        for (i=0;i<yd;i++) {
   467          m = hd(&x,i+j)-hd(&y,i)-b;
   468          if (m < 0) {
   469            b = 1;
   470            m = HLMAX + 1 + m;
   471          }
   472          else
   473            b = 0;
   474          if ((i+j)%2)
   475            x.p[(i+j)/2] = LOW(x.p[(i+j)/2]) | (m << HALFDIGITBITS);
   476          else
   477            x.p[(i+j)/2] = (HIGH(x.p[(i+j)/2]) << HALFDIGITBITS) | m;
   478        }
   479        if (b) {
   480          if ((j+i)%2)
   481            x.p[(i+j)/2] -= b << HALFDIGITBITS;
   482          else
   483            x.p[(i+j)/2] -= b;
   484        }
   485      }
   486      if (j%2)
   487        q.p[j/2] |= qhat << HALFDIGITBITS;
   488      else
   489        q.p[j/2] |= qhat;
   490    }
   491    mpz_realloc(mrb,&r,(size_t)(yy->sz));
   492    zero(&r);
   493    urshift(mrb,&r,&x,ns);
   494    mpz_set(mrb,rr,&r);
   495    mpz_set(mrb,qq,&q);
   496    mpz_clear(mrb,&x); mpz_clear(mrb,&y);
   497    mpz_clear(mrb,&q); mpz_clear(mrb,&r);
   498  }
