   500  static void
   501  mpz_mdiv(mrb_state *mrb, mpz_t *q, mpz_t *x, mpz_t *y)
   502  {
   503    mpz_t r;
   504    short sn1 = x->sn, sn2 = y->sn, qsign;
   505    if (uzero(x)) {
   506      mpz_init_set_int(mrb, q, 0);
   507      return;
   508    }
   509    mpz_init(mrb,&r);
   510    udiv(mrb,q,&r,x,y);
   511    qsign = q->sn = sn1*sn2;
   512    if (uzero(q))
   513      q->sn = 0;
   514    /* now if r != 0 and q < 0 we need to round q towards -inf */
   515    if (!uzero(&r) && qsign < 0)
   516      mpz_sub_int(mrb,q,q,1);
   517    mpz_clear(mrb,&r);
   518  }
